// Runtime view over the vendored icon sprite (ticket 06, extended).
//
// icon-catalog.json is the hand-authored source of truth (edited by humans);
// icon-sprite.generated.ts is the vendored SVG art (regenerated by
// `pnpm icons:gen`). This module joins them and derives the search keywords,
// so the palette and the `icon` shape share one lookup.
//
// Snapshots persist only the icon `id` string (e.g. "logos:aws-lambda"); the
// SVG bytes never enter a board.

import catalog from "@/pages/dashboard/draw/icon-catalog.json";
import { ICON_SPRITE, type SpriteIcon } from "@/pages/dashboard/draw/icon-sprite.generated";

export interface IconEntry {
  /** Full Iconify id, e.g. "logos:aws-lambda". Persisted in shape props. */
  id: string;
  /** Family id, e.g. "aws". */
  family: string;
  /** Family label, e.g. "AWS". */
  familyLabel: string;
  /** Human label, e.g. "Lambda". */
  title: string;
  /** Sub-category within the family, e.g. "Compute". */
  category: string;
  /** Lowercased search terms. */
  keywords: string[];
  sprite: SpriteIcon;
}

export interface IconFamily {
  id: string;
  label: string;
  categories: string[];
  icons: IconEntry[];
}

interface RawIcon {
  name: string;
  title: string;
  category: string;
  prefix?: string;
}

interface RawFamily {
  id: string;
  label: string;
  prefix: string;
  categories: string[];
  icons: RawIcon[];
}

interface RawCatalog {
  families: RawFamily[];
}

const data = catalog as unknown as RawCatalog;

// Shown when a snapshot references an iconId this build doesn't know (e.g. a
// board made by a newer client) so the shape still renders something visible.
export const FALLBACK_SPRITE: SpriteIcon = {
  viewBox: "0 0 24 24",
  body:
    '<path fill="none" stroke="currentColor" stroke-width="1.5" d="M4 4h16v16H4z"/>' +
    '<path fill="none" stroke="currentColor" stroke-width="1.5" d="M9 9.5a3 3 0 1 1 3 3v1.5"/>' +
    '<circle cx="12" cy="17.5" r="0.75" fill="currentColor"/>',
};

function tokenize(s: string): string[] {
  return s.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
}

export const ICON_FAMILIES: IconFamily[] = data.families.map((f) => {
  const icons: IconEntry[] = f.icons.map((i) => {
    const id = `${i.prefix ?? f.prefix}:${i.name}`;
    return {
      id,
      family: f.id,
      familyLabel: f.label,
      title: i.title,
      category: i.category,
      // "aws" (family label), category, the id's own parts ("aws","lambda"),
      // and the title words — so "aws", "compute" and "lambda" all resolve.
      keywords: Array.from(
        new Set([f.label, f.id, i.category, i.title, ...tokenize(i.name), ...tokenize(i.title)]),
      ),
      sprite: ICON_SPRITE[id] ?? FALLBACK_SPRITE,
    };
  });
  return { id: f.id, label: f.label, categories: f.categories, icons };
});

export const ICON_ENTRIES: IconEntry[] = ICON_FAMILIES.flatMap((f) => f.icons);

const ICON_BY_ID = new Map(ICON_ENTRIES.map((e) => [e.id, e]));

// Legacy snapshots (pre-generic-icon) stored bare AWS ids like "aws-ec2".
// Resolve those against the logos collection so old boards still render.
function resolve(id: string): IconEntry | undefined {
  if (ICON_BY_ID.has(id)) return ICON_BY_ID.get(id);
  if (!id.includes(":")) return ICON_BY_ID.get(`logos:${id}`);
  return undefined;
}

export function iconEntry(id: string): IconEntry | undefined {
  return resolve(id);
}

// The full human label for an icon: family plus name, e.g. "AWS Lambda". Used
// as the default text for a placed icon's label so it reads unambiguously.
export function iconLabel(id: string): string {
  const entry = resolve(id);
  return entry ? `${entry.familyLabel} ${entry.title}` : id;
}

export function iconSprite(id: string): SpriteIcon {
  return resolve(id)?.sprite ?? FALLBACK_SPRITE;
}
